		if statErr == nil {
			if info.IsDir() {
				return false, fmt.Errorf("ref %s is a directory", refName)
			}
			return false, nil
		}
		if !errors.Is(statErr, os.ErrNotExist) {
			return false, fmt.Errorf("inspect ref %s: %w", refName, statErr)
